/** Paired raw callback contracts: undeclared custom statement metadata versus owned native quantities. */
class LmdbNativeAndUnknownBindingContractTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI CODE = VF.createIRI("urn:lineage:code");
	private static final IRI OUTER = VF.createIRI("urn:lineage:Outer");

	@ParameterizedTest
	@MethodSource("scheduledVariants")
	void scheduledSelectionPreservesOnlyAuthenticatedPhysicalBindings(String variant, Lane lane,
			@TempDir File directory) {
		BindingSetAssignment values = variant.equals("duplicate")
				? values("kind", "keep0", "keep1", "keep1")
				: kinds();
		if (variant.equals("graph-context")) {
			values.setBindingNames(Set.of("graph"));
			values.setBindingSets(List.of(new ListBindingSet(List.of("graph"), VF.createIRI("urn:lineage:graph"))));
		}
		TupleExpr finiteInput = values;
		String object = variant.equals("graph-context") ? "future" : "kind";
		var appendedPattern = new StatementPattern(Var.of("target"), Var.of("predicate", CODE), Var.of(object));
		if (variant.equals("graph-context")) {
			appendedPattern = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("target"),
					Var.of("predicate", CODE), Var.of(object), Var.of("graph"));
		}
		TupleExpr residual = new Filter(new Join(code(), appendedPattern),
				new Compare(Var.of("kind"), new ValueConstant(VF.createLiteral("keep1"))));
		if (variant.equals("nested")) {
			residual = new Filter(residual, new Bound(Var.of("kind")));
		}
		Join root = new Join(finiteInput, residual);
		var call = PackedCostTestSupport.binaryOperator(PlanningGraphDomain.defaultGraph(), root);
		var filters = new ArrayList<Integer>();
		int innerJoin = call.rightRelationId();
		while (call.query().isFilter(innerJoin)) {
			filters.add(innerJoin);
			innerJoin = call.query().childRelationId(innerJoin, 0);
		}
		int codeId = call.query().childRelationId(innerJoin, 0);
		int appendedId = call.query().childRelationId(innerJoin, 1);
		long expectedRows = switch (variant) {
		case "duplicate" -> 8L;
		case "graph-context" -> 0L;
		default -> 4L;
		};
		withSession(directory, root, call, lane, (session, runtime) -> {
			PackedCostEstimate finiteValues = leaf(session, call, call.leftRelationId());
			var codeLeaf = leaf(session, call, codeId);
			var isolated = leaf(session, call, appendedId);
			if (variant.equals("component")) {
				isolated.setComponentRows(isolated.outputRows(), isolated.workRows());
			} else if (variant.equals("inclusive")) {
				isolated.setReplacesChildWork(true);
			}
			assertTrue(finiteValues.evidenceStateId() > 0);
			assertTrue(codeLeaf.evidenceStateId() > 0);
			var input = new PackedCostEstimate();
			input.setRows(finiteValues.outputRows() * codeLeaf.outputRows(),
					finiteValues.workRows() + codeLeaf.workRows());
			session.refineIntermediateJoin(call.operatorContext(finiteValues.outputRows(), codeLeaf.outputRows(),
					finiteValues.evidenceStateId(), codeLeaf.evidenceStateId()), input);
			assertTrue(input.evidenceStateId() > 0, "the supplied prefix comes from both actual leaf states");
			for (int i = filters.size() - 1; i >= 0; i--) {
				var selected = new PackedCostEstimate();
				selected.setRows(input.outputRows(), input.workRows() + input.outputRows());
				session.refineOperator(filters.get(i), call.operatorContext(input.outputRows(), Double.NaN,
						input.evidenceStateId(), 0), selected);
				assertTrue(selected.evidenceStateId() > 0);
				assertDeclinedPopulationLearning(selected);
				input = selected;
			}
			if (variant.startsWith("retained-") || variant.startsWith("physical-")) {
				var retainedContext = spy(call.emptyContext());
				when(retainedContext.evidenceStateId()).thenReturn(input.evidenceStateId());
				var retained = new PackedCostEstimate();
				double retainedRows = 17.0d;
				retained.setRows(retainedRows, 23.0d);
				if (variant.startsWith("physical-")) {
					retained.putPlannedStringMetric("optimizer.physicalJoinImplementation", "dependent-iteration");
				}
				session.refineIntermediateJoin(retainedContext, retained);
				assertEquals(retainedRows, retained.outputRows(), 0.0d,
						"a retained binding source cannot restore or fabricate a logical population");
				assertDeclinedPopulationLearning(retained);
				input = retained;
			}
			int[] prefix = { call.leftRelationId(), codeId };
			var context = PackedCostTestSupport.restrictedPrefixContext(prefix, prefix.length, input.outputRows(),
					input.evidenceStateId());
			// Compare against the ordinary declined append, including its required erasure of leaf evidence.
			session.appendFactor(appendedId,
					PackedCostTestSupport.restrictedPrefixContext(prefix, prefix.length, input.outputRows(), 0),
					isolated);
			assertEquals(0, isolated.evidenceStateId());
			assertDeclinedPopulationLearning(isolated);
			double[] before = physicalNumericContract(isolated);
			var scope = isolated.costScope();
			String source = isolated.estimateSource();
			String fusion = isolated.estimateFusion();
			var guarantee = isolated.evidenceGuarantee();
			var disposition = isolated.evidenceDisposition();
			boolean contextual = isolated.hasContextualOutputRows();
			boolean component = isolated.hasComponentOutputRows();
			boolean dependent = isolated.hasDependentCostComponents();
			session.appendFactor(appendedId, context, isolated);
			if (lane == Lane.UNKNOWN) {
				assertArrayEquals(before, physicalNumericContract(isolated),
						"physical binding metadata must retain every isolated numeric and priced invocation unit");
				assertEquals(scope, isolated.costScope());
				assertEquals(contextual, isolated.hasContextualOutputRows());
				assertEquals(component, isolated.hasComponentOutputRows());
				assertEquals(dependent, isolated.hasDependentCostComponents());
				assertEquals(source, isolated.estimateSource());
				assertEquals(fusion, isolated.estimateFusion());
				assertEquals(guarantee, isolated.evidenceGuarantee());
				assertEquals(disposition, isolated.evidenceDisposition());
				assertEquals(0, isolated.evidenceStateId());
				assertDeclinedPopulationLearning(isolated);
				boolean boundObject = variant.equals("plain") || variant.equals("nested") || variant.equals("duplicate")
						|| variant.equals("inclusive") || variant.equals("retained-same")
						|| variant.equals("physical-same");
				assertEquals(boundObject ? 6 : 2, isolated.lookupComponentMask(),
						"only actual assured inputs may supply O; encoded future children and raw flags cannot");
				if (boundObject) {
					assertEquals("posc", isolated.indexName());
					assertEquals(2, isolated.indexPrefixLength());
					assertEquals("prefixScan", isolated.accessMode());
				}
			} else {
				Set<String> supplied = variant.equals("graph-context") ? Set.of("graph") : Set.of("kind");
				assertOwnedNative(runtime, call, appendedId, supplied, context.prefixRows(), isolated,
						"scheduled/" + variant);
			}

		}, expectedRows);
	}

	@ParameterizedTest
	@MethodSource("joinedVariants")
	void joinedSelectedInputCombinesOnlyPhysicalBindingAssurances(String route, Lane lane, @TempDir File directory) {
		var appended = new StatementPattern(Var.of("target"), Var.of("predicate", CODE), Var.of("kind"));
		var residual = new Filter(new Join(code(), appended),
				new Compare(Var.of("kind"), new ValueConstant(VF.createLiteral("keep1"))));
		Join root = new Join(new Join(kinds(), residual), outer());
		var call = PackedCostTestSupport.binaryOperator(PlanningGraphDomain.defaultGraph(), root);
		int kindId = call.query().childRelationId(call.leftRelationId(), 0);
		int filterId = call.query().childRelationId(call.leftRelationId(), 1);
		int bodyId = call.query().childRelationId(filterId, 0);
		int codeId = call.query().childRelationId(bodyId, 0);
		int appendedId = call.query().childRelationId(bodyId, 1);
		withSession(directory, root, call, lane, (session, runtime) -> {
			var kinds = leaf(session, call, kindId);
			var code = leaf(session, call, codeId);
			var outer = leaf(session, call, call.rightRelationId());
			var input = new PackedCostEstimate();
			input.setRows(kinds.outputRows() * code.outputRows(), kinds.workRows() + code.workRows());
			session.refineIntermediateJoin(call.operatorContext(kinds.outputRows(), code.outputRows(),
					kinds.evidenceStateId(), code.evidenceStateId()), input);
			var selected = new PackedCostEstimate();
			selected.setRows(input.outputRows(), input.workRows() + input.outputRows());
			session.refineOperator(filterId,
					call.operatorContext(input.outputRows(), Double.NaN, input.evidenceStateId(), 0), selected);
			assertTrue(selected.evidenceStateId() > 0);
			assertDeclinedPopulationLearning(selected);
			var joined = new PackedCostEstimate();
			joined.setRows(selected.outputRows() * outer.outputRows(), selected.workRows() + outer.workRows());
			var context = call.operatorContext(selected.outputRows(), outer.outputRows(), selected.evidenceStateId(),
					outer.evidenceStateId());
			if (route.equals("operator")) {
				session.refineOperator(call.operatorRelationId(), context, joined);
			} else {
				session.refineIntermediateJoin(context, joined);
			}
			assertTrue(joined.evidenceStateId() > 0);
			assertDeclinedPopulationLearning(joined);
			if (route.equals("nested")) {
				var nested = new PackedCostEstimate();
				nested.setRows(joined.outputRows(), joined.workRows() + joined.outputRows());
				session.refineOperator(filterId,
						call.operatorContext(joined.outputRows(), Double.NaN, joined.evidenceStateId(), 0), nested);
				joined = nested;
				assertTrue(joined.evidenceStateId() > 0);
				assertDeclinedPopulationLearning(joined);
			}
			var isolated = leaf(session, call, appendedId);
			int[] raw = { kindId, codeId, call.rightRelationId() };
			session.appendFactor(appendedId,
					PackedCostTestSupport.restrictedPrefixContext(raw, raw.length, joined.outputRows(), 0), isolated);
			double[] before = physicalNumericContract(isolated);
			session.appendFactor(appendedId, PackedCostTestSupport.restrictedPrefixContext(raw, raw.length,
					joined.outputRows(), joined.evidenceStateId()), isolated);
			if (lane == Lane.UNKNOWN) {
				assertArrayEquals(before, physicalNumericContract(isolated));
				assertEquals(0, isolated.evidenceStateId());
				assertDeclinedPopulationLearning(isolated);
				assertEquals(6, isolated.lookupComponentMask());
			} else {
				assertOwnedNative(runtime, call, appendedId, Set.of("kind"), joined.outputRows(), isolated,
						"joined/" + route);
			}

		}, 12L);
	}

	private static void assertDeclinedPopulationLearning(PackedCostEstimate estimate) {
		var contract = estimate.runtimeFeedbackContract();
		for (int admission : new int[] { RuntimeFeedbackContract.ADMIT_LOGICAL, RuntimeFeedbackContract.ADMIT_FILTER,
				RuntimeFeedbackContract.ADMIT_SEMI_ANTI, RuntimeFeedbackContract.ADMIT_LIFECYCLE,
				RuntimeFeedbackContract.EXACT_FACT_ELIGIBLE }) {
			assertFalse(contract != null && contract.admits(admission),
					"physical bindings cannot qualify a different logical input population");
		}
	}

	private static double[] physicalNumericContract(PackedCostEstimate estimate) {
		return new double[] { estimate.outputRows(), estimate.workRows(), estimate.sequentialRows(),
				estimate.randomSeeks(), estimate.iteratorOpens(), estimate.expressionEvaluations(),
				estimate.hashBuildRows(),
				estimate.hashProbeRows(), estimate.pathExpansions(), estimate.resultRows(), estimate.remoteCalls(),
				estimate.peakMemoryRows(), estimate.accessRows(), estimate.invocations(), estimate.startupOnceWork(),
				estimate.dependentInvocationCount(), estimate.hitProbability(), estimate.firstMatchWork(),
				estimate.exhaustionWork(), estimate.rebindWork(), estimate.closeWork(), estimate.outputWork(),
				estimate.distinctKeyMisses(), estimate.cacheHits(), estimate.cacheMisses(), estimate.cacheEvictions(),
				estimate.materializationBuilds(), estimate.materializationLookups(), estimate.memorySpillWork(),
				estimate.objectiveLower(), estimate.objectivePoint(), estimate.objectiveUpper() };
	}

	private static PackedCostEstimate leaf(PackedCostSession session,
			PackedCostTestSupport.BinaryCostCall call, int relation) {
		var output = new PackedCostEstimate();
		session.estimateLeaf(relation, call.emptyContext(), output);
		return output;
	}

	private static void withSession(File directory, TupleExpr root, PackedCostTestSupport.BinaryCostCall call,
			Lane lane, BiConsumer<PackedCostSession, LmdbEstimatorRuntime> check, long expectedRows) {
		LmdbStore store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			try (var connection = repository.getConnection()) {
				connection.begin();
				for (int i = 0; i < 3; i++) {
					connection.add(VF.createIRI("urn:lineage:outer:" + i), RDF.TYPE, OUTER);
				}
				for (int i = 0; i < 5; i++) {
					connection.add(VF.createIRI("urn:lineage:inner:" + i), CODE, VF.createLiteral("keep" + i % 2));
				}
				for (int i = 0; i < 3; i++) {
					connection.add(VF.createIRI("urn:lineage:noise:" + i), CODE, VF.createLiteral("drop"));
				}
				connection.commit();
			}
			assertEquals(FrontierStatisticsAvailability.READY, store.rebuildFrontierStatistics().availability());
			var backing = store.getSailStore();
			try (SailSource source = backing.getExplicitSailSource().fork();
					SailDataset dataset = source.dataset(IsolationLevels.SNAPSHOT_READ)) {
				var tripleSource = new SailDatasetTripleTermSource(backing.getValueFactory(), dataset);
				var statistics = backing.getEvaluationStatistics();
				var runtime = ((LmdbEstimatorRuntimeProvider) statistics).estimatorRuntime();
				var strategy = store.getEvaluationStrategyFactory()
						.createEvaluationStrategy(null, tripleSource, statistics);
				new LmdbQueryOptimizerPipeline(strategy, tripleSource, statistics)
						.withPreparedQueryEntry(new QueryRoot(root.clone()), null, EmptyBindingSet.getInstance(),
								(prepared, cascades) -> {
									var costRuntime = lane == Lane.NATIVE ? runtime : unknownStatementProducer(runtime);
									var model = new LmdbPackedCostModel(costRuntime, tripleSource.getSnapshotEpoch(),
											true,
											tripleSource, strategy);
									try (var session = model.openSession(call.query())) {
										if (expectedRows >= 0L) {
											long actualRows = 0L;
											try (var result = strategy.precompile(root.clone())
													.evaluate(EmptyBindingSet.getInstance())) {
												while (result.hasNext()) {
													BindingSet row = result.next();
													actualRows++;
												}
											}
											assertEquals(expectedRows, actualRows,
													"actual public native execution authenticates the exact supplied child bag");
										}
										check.accept(session, runtime);
									}
									return null;
								});
			}
		} finally {
			repository.shutDown();
		}
	}

	private static BindingSetAssignment values(String name, String... entries) {
		var assignment = new BindingSetAssignment();
		assignment.setBindingNames(Set.of(name));
		assignment.setBindingSets(Arrays.stream(entries)
				.<BindingSet>map(value -> new ListBindingSet(List.of(name), VF.createLiteral(value)))
				.toList());
		return assignment;
	}

	private static BindingSetAssignment kinds() {
		var assignment = new BindingSetAssignment();
		assignment.setBindingNames(Set.of("kind"));
		assignment.setBindingSets(List.of(new ListBindingSet(List.of("kind"), VF.createLiteral("keep0")),
				new ListBindingSet(List.of("kind"), VF.createLiteral("keep1"))));
		return assignment;
	}

	private static StatementPattern code() {
		return new StatementPattern(Var.of("inner"), Var.of("code", CODE), Var.of("kind"));
	}

	private static StatementPattern outer() {
		return new StatementPattern(Var.of("outer"), Var.of("type", RDF.TYPE), Var.of("outerType", OUTER));
	}

	private static Stream<Arguments> scheduledVariants() {
		return Stream.of("plain", "nested", "duplicate", "component", "inclusive", "retained-same",
				"physical-same", "graph-context").flatMap(v -> Stream.of(Lane.values()).map(l -> Arguments.of(v, l)));
	}

	private static Stream<Arguments> joinedVariants() {
		return Stream.of("intermediate", "operator", "nested")
				.flatMap(v -> Stream.of(Lane.values()).map(l -> Arguments.of(v, l)));
	}

	static LmdbEstimatorRuntime unknownStatementProducer(LmdbEstimatorRuntime nativeRuntime) {
		LmdbEstimatorRuntime custom = spy(nativeRuntime);
		doAnswer(invocation -> {
			TupleExpr expression = invocation.getArgument(0);
			JoinFactorCostModel.CostContext context = invocation.getArgument(1);
			return nativeRuntime.factorCost(expression, context)
					.map(estimate -> expression instanceof StatementPattern
							? estimate.withRowScope(JoinFactorCostModel.RowScope.UNKNOWN)
							: estimate);
		}).when(custom).factorCost(any(TupleExpr.class), any(JoinFactorCostModel.CostContext.class));
		return custom;
	}

	private static void assertOwnedNative(LmdbEstimatorRuntime runtime, PackedCostTestSupport.BinaryCostCall call,
			int relation, Set<String> supplied, double rows, PackedCostEstimate actual, String reason) {
		var context = JoinFactorCostModel.CostContext.forOptimization(supplied, rows, Double.NaN, true, true,
				Map.of(), List.of()).withPrefixFactorsDescribeCurrentRows(false);
		var producer = runtime.factorCost(call.query().materializeRelation(relation), context).orElseThrow();
		assertEquals(JoinFactorCostModel.RowScope.FOR_CONTEXT, producer.getRowScope());
		assertTrue(producer.hasPhysicalAccessPath());
		assertTrue(producer.isRepeatedInvocationsCosted());
		Double invocations = producer.getDoubleMetrics().get("plannedRepeatedInvocations");
		assertNotNull(invocations);
		assertEquals(producer.getOutputRows(), actual.outputRows(), 0.0d, reason + ": native full ROW");
		assertTrue(actual.hasContextualOutputRows());
		assertFalse(actual.hasComponentOutputRows());
		assertEquals(invocations, actual.invocations(), 0.0d);
		assertEquals(producer.getAccessRowsBeforeFilter(), actual.accessRows(), 0.0d);
		assertEquals(producer.getAccessRowsBeforeFilter() * invocations, actual.sequentialRows(), 0.0d);
		assertEquals(invocations, actual.randomSeeks(), 0.0d);
		assertEquals(invocations, actual.iteratorOpens(), 0.0d);
		assertEquals(producer.getOutputRows(), actual.resultRows(), 0.0d);
		assertEquals(producer.getLookupComponentMask(), actual.lookupComponentMask());
		assertEquals(producer.getMissingLookupComponentMask(), actual.missingLookupComponentMask());
		assertEquals(producer.getStringMetrics().get("plannedIndexName"), actual.indexName());
		assertEquals(producer.getStringMetrics().get("plannedIndexAccessMode"), actual.accessMode());
		assertEquals(0.0d, actual.expressionEvaluations(), 0.0d);
		assertEquals(0.0d, actual.hashBuildRows(), 0.0d);
		assertEquals(0.0d, actual.hashProbeRows(), 0.0d);
		assertEquals(0.0d, actual.pathExpansions(), 0.0d);
		assertEquals(0.0d, actual.remoteCalls(), 0.0d);
		assertEquals(0.0d, actual.peakMemoryRows(), 0.0d);
		// A packed native statement prices scans, seeks, opens, and result production in separate axes.
		// The producer's raw scalar is not that complete typed WORK projection.
		double expectedSequentialRows = producer.getAccessRowsBeforeFilter() * invocations;
		double expectedTypedWork = expectedSequentialRows + invocations + invocations + producer.getOutputRows();
		assertEquals(expectedTypedWork, actual.workRows(), 0.0d, reason + ": native typed WORK projection");
		assertDeclinedPopulationLearning(actual);
		if (reason.endsWith("graph-context")) {
			assertFalse(producer.hasExactOutputRows(), "empty actual query and conservative estimate are separate");
			assertFalse(actual.evidenceGuarantee() == EvidenceGuarantee.DATABASE_EXACT);
		}
	}

	enum Lane {
		UNKNOWN,
		NATIVE
	}
}
